B.a6u=new A.fk("Scalar Subquery in SELECT","Fetch a single calculated value for each row","SELECT \n  t.id,\n  t.name,\n  (\n    SELECT COUNT(*)\n    FROM related_items r\n    WHERE r.parent_id = t.id\n  ) AS item_count\nFROM parent_table t;","Projection")
